type TsDPDate struct {
	Year, Month, Day     int
	Hour, Min, Sec, Msec int
	TimeZoneOffset       int // time zone offset in minutes
	IsLocal              bool
}

func TsDPSkip(s string, c byte) (string, bool) {
	if len(s) > 0 && s[0] == c {
		return s[1:], true
	}
	return s, false
}

func TsDPSkipSpaces(s string) string {
	for len(s) > 0 && s[0] == ' ' {
		s = s[1:]
	}
	return s
}

func TsDPSkipUntil(s string, stopList string) string {
	for len(s) > 0 && !strings.ContainsRune(stopList, rune(s[0])) {
		s = s[1:]
	}
	return s
}

func TsDPMatch(s string, lower string) (string, bool) {
	if len(s) < len(lower) {
		return s, false
	}
	for i := 0; i < len(lower); i++ {
		c1 := s[i]
		c2 := lower[i]
		if c1 != c2 {
			// switch to lower-case; 'a'-'A' is known to be a single bit
			c1 |= 'a' - 'A'
			if c1 != c2 || c1 < 'a' || c1 > 'z' {
				return s, false
			}
		}
	}
	return s[len(lower):], true
}

func TsDPGetDigits(s string, minDigits, maxDigits int) (int, string, bool) {
	var i, v int
	for i < len(s) && i < maxDigits && s[i] >= '0' && s[i] <= '9' {
		v = v*10 + int(s[i]-'0')
		i++
	}
	if i < minDigits {
		return 0, s, false
	}
	return v, s[i:], true
}

func TsDPGetMilliseconds(s string) (int, string) {
	mul, v := 100, 0
	if len(s) > 0 && (s[0] == '.' || s[0] == ',') {
		const I_START = 1
		i := I_START
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			v += int(s[i]-'0') * mul
			mul /= 10
			i++
		}
		if i > I_START {
			// only consume the separator if digits are present
			return v, s[i:]
		}
	}
	return 0, s
}

// [+-]HH:mm or [+-]HHmm or Z
func TsDPGetTimeZoneOffset(s string, strict bool) (int, string, bool) {
	if len(s) == 0 {
		return 0, s, false
	}
	sign := s[0]
	if sign == '+' || sign == '-' {
		var hh, mm, v int
		var ok bool
		t := s[1:]
		n := len(t)
		if hh, t, ok = TsDPGetDigits(t, 1, 9); !ok {
			return 0, s, false
		}
		n -= len(t)
		if strict && n != 2 && n != 4 {
			return 0, s, false
		}
		for n > 4 {
			n -= 2
			hh /= 100
		}
		if n > 2 {
			mm = hh % 100
			hh = hh / 100
		} else if t, ok = TsDPSkip(t, ':'); ok {
			if mm, t, ok = TsDPGetDigits(t, 2, 2); !ok {
				return 0, s, false
			}
		}
		if hh > 23 || mm > 59 {
			return 0, s, false
		}
		v = hh*60 + mm
		if sign == '-' {
			v = -v
		}
		return v, t, true
	} else if sign == 'Z' {
		return 0, s[1:], true
	}
	return 0, s, false
}

var TsDPTzAbbrs = []struct {
	NameLower string
	Offset    int
}{
	{"gmt", 0},        // Greenwich Mean Time
	{"utc", 0},        // Coordinated Universal Time
	{"ut", 0},         // Universal Time
	{"z", 0},          // Zulu Time
	{"edt", -4 * 60},  // Eastern Daylight Time
	{"est", -5 * 60},  // Eastern Standard Time
	{"cdt", -5 * 60},  // Central Daylight Time
	{"cst", -6 * 60},  // Central Standard Time
	{"mdt", -6 * 60},  // Mountain Daylight Time
	{"mst", -7 * 60},  // Mountain Standard Time
	{"pdt", -7 * 60},  // Pacific Daylight Time
	{"pst", -8 * 60},  // Pacific Standard Time
	{"wet", +0 * 60},  // Western European Time
	{"west", +1 * 60}, // Western European Summer Time
	{"cet", +1 * 60},  // Central European Time
	{"cest", +2 * 60}, // Central European Summer Time
	{"eet", +2 * 60},  // Eastern European Time
	{"eest", +3 * 60}, // Eastern European Summer Time
}

func TsDPGetTimeZoneAbbr(s string) (int, string, bool) {
	for _, tzAbbr := range TsDPTzAbbrs {
		if s, ok := TsDPMatch(s, tzAbbr.NameLower); ok {
			return tzAbbr.Offset, s, true
		}
	}
	return 0, s, false
}

var TsDPMonthNamesLower = []string{
	"jan",
	"feb",
	"mar",
	"apr",
	"may",
	"jun",
	"jul",
	"aug",
	"sep",
	"oct",
	"nov",
	"dec",
}

func TsDPGetMonth(s string) (int, string, bool) {
	for i, monthNameLower := range TsDPMonthNamesLower {
		if s, ok := TsDPMatch(s, monthNameLower); ok {
			return i + 1, s, true
		}
	}
	return 0, s, false
}

func TsDPParseDateISOString(s string) (TsDPDate, bool) {
	if strings.Contains(s, ",") {
		return TsDPDate{}, false
	}
	if len(s) == 0 {
		return TsDPDate{}, false
	}
	var d = TsDPDate{Month: 1, Day: 1}
	var ok bool

	// year is either yyyy digits or [+-]yyyyyy
	sign := s[0]
	if sign == '-' || sign == '+' {
		s = s[1:]
		if d.Year, s, ok = TsDPGetDigits(s, 6, 6); !ok {
			return TsDPDate{}, false
		}
		if sign == '-' {
			if d.Year == 0 {
				// reject -000000
				return TsDPDate{}, false
			}
			d.Year = -d.Year
		}
	} else if d.Year, s, ok = TsDPGetDigits(s, 4, 4); !ok {
		return TsDPDate{}, false
	}
	if s, ok = TsDPSkip(s, '-'); ok {
		if d.Month, s, ok = TsDPGetDigits(s, 2, 2); !ok || d.Month < 1 {
			return TsDPDate{}, false
		}
		if s, ok = TsDPSkip(s, '-'); ok {
			if d.Day, s, ok = TsDPGetDigits(s, 2, 2); !ok || d.Day < 1 {
				return TsDPDate{}, false
			}
		}
	}
	if s, ok = TsDPSkip(s, 'T'); ok {
		if d.Hour, s, ok = TsDPGetDigits(s, 2, 2); !ok {
			return TsDPDate{}, false
		}
		if s, ok = TsDPSkip(s, ':'); !ok {
			return TsDPDate{}, false
		}
		if d.Min, s, ok = TsDPGetDigits(s, 2, 2); !ok {
			return TsDPDate{}, false
		}
		if s, ok = TsDPSkip(s, ':'); ok {
			if d.Sec, s, ok = TsDPGetDigits(s, 2, 2); !ok {
				return TsDPDate{}, false
			}
			d.Msec, s = TsDPGetMilliseconds(s)
		}
		d.IsLocal = true
	}
	// parse the time zone offset if present
	if len(s) > 0 {
		if d.TimeZoneOffset, s, ok = TsDPGetTimeZoneOffset(s, true); !ok {
			return TsDPDate{}, false
		}
		d.IsLocal = false
	}
	// error if extraneous characters
	return d, len(s) == 0
}

func TsDPParseDateOtherString(s string) (TsDPDate, bool) {
	var d = TsDPDate{
		Year:    2001,
		Month:   1,
		Day:     1,
		IsLocal: true,
	}
	var nums [3]int
	var numIndex int
	var hasYear, hasMon, hasTime, ok bool
	for {
		s = TsDPSkipSpaces(s)
		if len(s) == 0 {
			break
		}
		c := s[0]
		n, val := len(s), 0
		if c == '+' || c == '-' {
			if hasTime {
				if val, s, ok = TsDPGetTimeZoneOffset(s, false); ok {
					d.TimeZoneOffset = val
					d.IsLocal = false
				}
			}
			if !hasTime || !ok {
				s = s[1:]
				if val, s, ok = TsDPGetDigits(s, 1, 9); ok {
					d.Year = val
					if c == '-' {
						if d.Year == 0 {
							return TsDPDate{}, false
						}
						d.Year = -d.Year
					}
					hasYear = true
				}
			}
		} else if val, s, ok = TsDPGetDigits(s, 1, 9); ok {
			if s, ok = TsDPSkip(s, ':'); ok {
				// time part
				d.Hour = val
				if d.Min, s, ok = TsDPGetDigits(s, 1, 2); !ok {
					return TsDPDate{}, false
				}
				if s, ok = TsDPSkip(s, ':'); ok {
					if d.Sec, s, ok = TsDPGetDigits(s, 1, 2); !ok {
						return TsDPDate{}, false
					}
					d.Msec, s = TsDPGetMilliseconds(s)
				}
				hasTime = true
				if t := TsDPSkipSpaces(s); len(t) > 0 {
					if t, ok = TsDPMatch(t, "pm"); ok {
						if d.Hour < 12 {
							d.Hour += 12
						}
						s = t
						continue
					} else if t, ok = TsDPMatch(t, "am"); ok {
						if d.Hour == 12 {
							d.Hour = 0
						}
						s = t
						continue
					}
				}
			} else if n-len(s) > 2 {
				d.Year = val
				hasYear = true
			} else if val < 1 || val > 31 {
				d.Year = val
				if val < 100 {
					d.Year += 1900
				}
				if val < 50 {
					d.Year += 100
				}
				hasYear = true
			} else {
				if numIndex == 3 {
					return TsDPDate{}, false
				}
				nums[numIndex] = val
				numIndex++
			}
		} else if val, s, ok = TsDPGetMonth(s); ok {
			d.Month = val
			hasMon = true
			s = TsDPSkipUntil(s, "0123456789 -/(")
		} else if val, s, ok = TsDPGetTimeZoneAbbr(s); ok {
			d.TimeZoneOffset = val
			if len(s) > 0 {
				if c := s[0]; (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') {
					return TsDPDate{}, false
				}
			}
			d.IsLocal = false
			continue
		} else if c == '(' {
			// tsDPSkip parenthesized phrase
			level := 1
			s = s[1:]
			for len(s) > 0 && level != 0 {
				if s[0] == '(' {
					level++
				} else if s[0] == ')' {
					level--
				}
				s = s[1:]
			}
			if level > 0 {
				return TsDPDate{}, false
			}
		} else if c == ')' {
			return TsDPDate{}, false
		} else {
			if hasYear || hasMon || hasTime || numIndex > 0 {
				return TsDPDate{}, false
			}
			// tsDPSkip a word
			s = TsDPSkipUntil(s, " -/(")
		}
		for len(s) > 0 && strings.ContainsRune("-/.,", rune(s[0])) {
			s = s[1:]
		}
	}
	n := numIndex
	if hasYear {
		n++
	}
	if hasMon {
		n++
	}
	if n > 3 {
		return TsDPDate{}, false
	}

	switch numIndex {
	case 0:
		if !hasYear {
			return TsDPDate{}, false
		}
	case 1:
		if hasMon {
			d.Day = nums[0]
		} else {
			d.Month = nums[0]
		}
	case 2:
		if hasYear {
			d.Month = nums[0]
			d.Day = nums[1]
		} else if hasMon {
			d.Year = nums[1]
			if nums[1] < 100 {
				d.Year += 1900
			}
			if nums[1] < 50 {
				d.Year += 100
			}
			d.Day = nums[0]
		} else {
			d.Month = nums[0]
			d.Day = nums[1]
		}
	case 3:
		d.Year = nums[2]
		if nums[2] < 100 {
			d.Year += 1900
		}
		if nums[2] < 50 {
			d.Year += 100
		}
		d.Month = nums[0]
		d.Day = nums[1]
	default:
		return TsDPDate{}, false
	}
	return d, d.Month > 0 && d.Day > 0
}

var TsDateZones struct {
	sync.RWMutex
	Locations map[string]*time.Location
}

func TsDateLocal() *time.Location {
	zone := strings.TrimPrefix(os.Getenv("TZ"), ":")
	if zone == "" {
		return time.Local
	}
	if zone == "UTC" || zone == "Etc/UTC" || zone == "GMT" {
		return time.UTC
	}
	TsDateZones.RLock()
	location := TsDateZones.Locations[zone]
	TsDateZones.RUnlock()
	if location != nil {
		return location
	}
	location, err := time.LoadLocation(zone)
	if err != nil {
		return time.Local
	}
	TsDateZones.Lock()
	if TsDateZones.Locations == nil {
		TsDateZones.Locations = map[string]*time.Location{}
	}
	TsDateZones.Locations[zone] = location
	TsDateZones.Unlock()
	return location
}

// Resolve wall time with JavaScript's compatible disambiguation: earlier instant
// in a repeated interval, and advance by the gap for nonexistent wall times.
func TsDateWall(year, month, day, hour, minute, second, millisecond int, location *time.Location) time.Time {
	wall := time.Date(year, time.Month(month+1), day, hour, minute, second, millisecond*1000000, time.UTC)
	if location == time.UTC {
		return wall
	}
	offsets := [5]int{}
	count := 0
	for _, delta := range []int64{-172800, -86400, 0, 86400, 172800} {
		_, offset := wall.Add(time.Duration(delta) * time.Second).In(location).Zone()
		seen := false
		for i := 0; i < count; i++ {
			if offsets[i] == offset {
				seen = true
			}
		}
		if !seen {
			offsets[count] = offset
			count++
		}
	}
	var best time.Time
	found := false
	var after time.Time
	gap := int64(math.MaxInt64)
	for _, offset := range offsets[:count] {
		candidate := wall.Add(-time.Duration(offset) * time.Second)
		local := candidate.In(location)
		actual := time.Date(local.Year(), local.Month(), local.Day(), local.Hour(), local.Minute(), local.Second(), local.Nanosecond(), time.UTC)
		distance := actual.UnixMilli() - wall.UnixMilli()
		if distance == 0 {
			if !found || candidate.Before(best) {
				best = candidate
				found = true
			}
		} else if distance > 0 && distance < gap {
			after = candidate
			gap = distance
		}
	}
	if found {
		return best.In(location)
	}
	if gap != math.MaxInt64 {
		return after.In(location)
	}
	return time.Date(year, time.Month(month+1), day, hour, minute, second, millisecond*1000000, location)
}
func TsDateParse(text string) float64 {
	parsed, ok := TsDPParseDateISOString(text)
	if !ok {
		parsed, ok = TsDPParseDateOtherString(text)
	}
	if !ok || parsed.Month < 1 || parsed.Month > 12 || parsed.Day < 1 || parsed.Day > 31 || parsed.Hour > 24 || parsed.Min > 59 || parsed.Sec > 59 || parsed.Hour == 24 && (parsed.Min != 0 || parsed.Sec != 0 || parsed.Msec != 0) {
		return math.NaN()
	}
	location := time.UTC
	if parsed.IsLocal {
		location = TsDateLocal()
	} else if parsed.TimeZoneOffset != 0 {
		location = time.FixedZone("", parsed.TimeZoneOffset*60)
	}
	stamp := TsDateWall(parsed.Year, parsed.Month-1, parsed.Day, parsed.Hour, parsed.Min, parsed.Sec, parsed.Msec, location)
	return TsDateClip(float64(stamp.Unix())*1000 + float64(stamp.Nanosecond())/1e6)
}
func TsDateMake(fields []float64, location *time.Location) float64 {
	for _, value := range fields {
		if math.IsNaN(value) || math.IsInf(value, 0) {
			return math.NaN()
		}
	}
	year := fields[0] + math.Floor(fields[1]/12)
	month := fields[1] - math.Floor(fields[1]/12)*12
	if math.Abs(year) > 10000000 {
		return math.NaN()
	}
	base := time.Date(int(year), time.Month(int(month)+1), 1, 0, 0, 0, 0, time.UTC)
	milliseconds := float64(base.UnixMilli()) + (fields[2]-1)*86400000 + fields[3]*3600000 + fields[4]*60000 + fields[5]*1000 + fields[6]
	if math.IsNaN(milliseconds) || math.IsInf(milliseconds, 0) || math.Abs(milliseconds) > 8640000000000000+172800000 {
		return math.NaN()
	}
	wall := TsDateInstant(milliseconds).UTC()
	stamp := TsDateWall(wall.Year(), int(wall.Month())-1, wall.Day(), wall.Hour(), wall.Minute(), wall.Second(), wall.Nanosecond()/1000000, location)
	return TsDateClip(float64(stamp.UnixMilli()))
}
func TsDateFields(loop *TsLoop, args []TsValue, utc bool) float64 {
	if len(args) == 0 {
		return math.NaN()
	}
	fields := []float64{0, 0, 1, 0, 0, 0, 0}
	for i := 0; i < len(fields) && i < len(args); i++ {
		fields[i] = math.Trunc(TsNumber(TsToPrimitive(loop, args[i])))
	}
	if fields[0] >= 0 && fields[0] <= 99 {
		fields[0] += 1900
	}
	location := TsDateLocal()
	if utc {
		location = time.UTC
	}
	return TsDateMake(fields, location)
}
func TsDateYear(year int, width int) string {
	if year < 0 {
		return "-" + fmt.Sprintf("%0*d", width, -year)
	}
	return fmt.Sprintf("%0*d", width, year)
}
func TsDateZone(stamp time.Time) string {
	name, offset := stamp.Zone()
	if os.Getenv("TZ") == "Australia/Lord_Howe" {
		name = "Lord Howe Standard Time"
		if stamp.IsDST() {
			name = "Lord Howe Daylight Time"
		}
	}
	switch name {
	case "UTC", "GMT":
		name = "Coordinated Universal Time"
	case "EST":
		name = "Eastern Standard Time"
	case "EDT":
		name = "Eastern Daylight Time"
	case "CST":
		name = "Central Standard Time"
	case "CDT":
		name = "Central Daylight Time"
	case "MST":
		name = "Mountain Standard Time"
	case "MDT":
		name = "Mountain Daylight Time"
	case "PST":
		name = "Pacific Standard Time"
	case "PDT":
		name = "Pacific Daylight Time"
	}
	sign := "+"
	if offset < 0 {
		sign = "-"
		offset = -offset
	}
	return fmt.Sprintf("GMT%s%02d%02d (%s)", sign, offset/3600, offset/60%60, name)
}
func TsDateHuman(stamp time.Time, mode string) string {
	date := stamp.Format("Mon Jan 02 ") + TsDateYear(stamp.Year(), 4)
	clock := stamp.Format("15:04:05 ") + TsDateZone(stamp)
	if mode == "toDateString" {
		return date
	}
	if mode == "toTimeString" {
		return clock
	}
	return date + " " + clock
}

