			constructor.Properties = TsNewObject()
			constructor.Properties.Set(loop, "prototype", TsObjectValue(root))
			constructor.Properties.Descriptors = map[string]*TsDescriptor{"prototype": {}}
			root.Set(loop, "prototype", TsObjectValue(prototype))
			root.Set(loop, "constructor", TsFunctionValue(constructor))
