		object.Set(loop, "Function", TsFunctionConstructor(loop))
		object.Set(loop, "Array", TsBuiltinClass(loop, "Array"))
		object.Set(loop, "String", TsStringConstructor(loop))
		object.Set(loop, "Number", TsNumberConstructor(loop))
		object.Set(loop, "Boolean", TsBooleanConstructor(loop))
