	if exponent == 0 {
		if fraction == 0 {
			bits = sign
		} else {
			exponent = 1
			for fraction&0x400 == 0 {
				fraction <<= 1
				exponent--
			}
			fraction &= 0x3ff
			bits = sign | ((exponent + 112) << 23) | (fraction << 13)
		}
	} else if exponent == 31 {
		bits = sign | 0x7f800000 | (fraction << 13)
	} else {
		bits = sign | ((exponent + 112) << 23) | (fraction << 13)
	}
	return float64(math.Float32frombits(bits))
